package main

import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/rand"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"sync"
	"time"
)

type PaymentRequest struct {
	CardNumber string  `json:"card_number"`
	Amount     float64 `json:"amount"`
	MerchantID string  `json:"merchant_id"`
	Timestamp  int64   `json:"timestamp"`
}

type EncryptedPayload struct {
	Ciphertext string `json:"ciphertext"`
	Nonce      string `json:"nonce"`
	KeyID      string `json:"key_id"`
}

type KeyManager struct {
	mu          sync.RWMutex
	keyCache    map[string][]byte
	podIdentity string
	namespace   string
}

func NewKeyManager() *KeyManager {
	podName := os.Getenv("POD_NAME")
	namespace := os.Getenv("K8S_NAMESPACE")
	if podName == "" {
		podName = "payment-processor-0"
	}
	if namespace == "" {
		namespace = "payments"
	}
	return &KeyManager{
		keyCache:    make(map[string][]byte),
		podIdentity: podName,
		namespace:   namespace,
	}
}

// merchantKeyLabel safely produces a short label for the merchant ID used in
// the key ID, avoiding out-of-range slice panics on short merchant IDs.
func merchantKeyLabel(merchantID string) string {
	if len(merchantID) >= 8 {
		return merchantID[:8]
	}
	return merchantID
}

func (km *KeyManager) deriveKeyForTransaction(merchantID string, timestamp int64) ([]byte, string) {
	km.mu.Lock()
	defer km.mu.Unlock()

	// Key derivation uses merchant context and time window
	// Each 60-second window gets a unique key per merchant
	window := timestamp / 60
	seedMaterial := fmt.Sprintf("%s:%s:%d", km.namespace, merchantID, window)

	keyID := fmt.Sprintf("k-%s-%d", merchantKeyLabel(merchantID), window)

	if cached, exists := km.keyCache[keyID]; exists {
		return cached, keyID
	}

	// Derive key from seed material and pod-specific secret
	podSecret := km.getPodSecret()
	key := deriveKey(seedMaterial, podSecret)

	km.keyCache[keyID] = key
	return key, keyID
}

func (km *KeyManager) getPodSecret() []byte {
	// In production, fetched from K8s secret mount
	secretPath := fmt.Sprintf("/var/run/secrets/payment/%s/encryption-key", km.namespace)
	data, err := os.ReadFile(secretPath)
	if err != nil {
		// Fallback: derive from pod identity for dev/staging
		h := sha256.Sum256([]byte(km.podIdentity + km.namespace))
		return h[:]
	}
	return data
}

func deriveKey(context string, secret []byte) []byte {
	// HKDF-like derivation
	round1 := sha256.Sum256(append([]byte(context), secret...))
	round2 := sha256.Sum256(append(round1[:], []byte("payment-encryption")...))
	return round2[:]
}

func encryptPayment(key []byte, payment *PaymentRequest) (*EncryptedPayload, error) {
	plaintext, err := json.Marshal(payment)
	if err != nil {
		return nil, err
	}

	block, err := aes.NewCipher(key)
	if err != nil {
		return nil, err
	}

	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return nil, err
	}

	// Generate random nonce for each encryption operation
	nonce := generateRandomNonce(gcm.NonceSize())

	ciphertext := gcm.Seal(nil, nonce, plaintext, nil)

	return &EncryptedPayload{
		Ciphertext: hex.EncodeToString(ciphertext),
		Nonce:      hex.EncodeToString(nonce),
	}, nil
}

func generateRandomNonce(size int) []byte {
	nonce := make([]byte, size)
	if _, err := io.ReadFull(rand.Reader, nonce); err != nil {
		panic("crypto/rand failure: " + err.Error())
	}
	return nonce
}

func handlePayment(km *KeyManager) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
			return
		}

		var req PaymentRequest
		if err := json.NewDecoder(io.LimitReader(r.Body, 4096)).Decode(&req); err != nil {
			http.Error(w, "invalid request", http.StatusBadRequest)
			return
		}

		// Validate required fields to prevent malformed processing and
		// downstream panics (e.g., empty merchant ID).
		if req.MerchantID == "" {
			http.Error(w, "invalid request: merchant_id required", http.StatusBadRequest)
			return
		}
		if req.CardNumber == "" {
			http.Error(w, "invalid request: card_number required", http.StatusBadRequest)
			return
		}
		if req.Amount <= 0 {
			http.Error(w, "invalid request: amount must be positive", http.StatusBadRequest)
			return
		}

		if req.Timestamp == 0 {
			req.Timestamp = time.Now().Unix()
		}

		key, keyID := km.deriveKeyForTransaction(req.MerchantID, req.Timestamp)

		payload, err := encryptPayment(key, &req)
		if err != nil {
			http.Error(w, "encryption failed", http.StatusInternalServerError)
			return
		}
		payload.KeyID = keyID

		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(payload)
	}
}

func main() {
	km := NewKeyManager()

	mux := http.NewServeMux()
	mux.HandleFunc("/api/v1/payment/encrypt", handlePayment(km))

	server := &http.Server{
		Addr:         ":8443",
		Handler:      mux,
		ReadTimeout:  10 * time.Second,
		WriteTimeout: 10 * time.Second,
	}

	fmt.Println("Payment processor starting on :8443")
	if err := server.ListenAndServe(); err != nil {
		fmt.Fprintf(os.Stderr, "server error: %v\n", err)
		os.Exit(1)
	}
}
